const a={title:"MiPhi Enterprise Storage | DeepIQ",description:"MiPhi enterprise storage solutions from DeepIQ — high-performance SSD infrastructure engineered for AI, cloud, data centres and modern enterprise workloads.",theme:"#050506",body:`<a class="skip-link" href="#main-content">Skip to content</a>
    <div class="reading-progress" aria-hidden="true"><span></span></div>
    <div class="cursor-aura" aria-hidden="true"></div>

    <header class="miphi-header" data-header>
      <a class="deepiq-brand" href="/" aria-label="DeepIQ home">
        <img src="/deepiq-logo.svg" alt="" />
        <span>DEEP</span><b>IQ</b>
      </a>
      <nav class="desktop-nav" aria-label="MiPhi page navigation">
        <a href="#foundation">The Foundation</a>
        <a href="#workloads">Workloads</a>
        <a href="#engineering">Engineering</a>
        <a href="#sri-lanka">MiPhi in Sri Lanka</a>
      </nav>
      <a class="header-cta" href="/#contact">Explore with DeepIQ <span aria-hidden="true">↗</span></a>
      <button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open navigation"><span></span><span></span></button>
    </header>

    <div class="mobile-nav" id="mobile-nav" aria-hidden="true">
      <nav aria-label="Mobile navigation">
        <a href="#foundation"><span>01</span>The Foundation</a>
        <a href="#workloads"><span>02</span>Workloads</a>
        <a href="#engineering"><span>03</span>Engineering</a>
        <a href="#sri-lanka"><span>04</span>MiPhi in Sri Lanka</a>
        <a href="/#contact"><span>05</span>Talk to DeepIQ</a>
      </nav>
      <a class="mobile-back" href="/">← Back to DeepIQ</a>
    </div>

    <main id="main-content">
      <section class="miphi-hero" id="top" aria-labelledby="miphi-title">
        <div class="hero-image" data-parallax aria-hidden="true"></div>
        <canvas id="data-stream-canvas" aria-hidden="true"></canvas>
        <div class="hero-grid" aria-hidden="true"></div>
        <div class="hero-vignette" aria-hidden="true"></div>
        <div class="hero-content">
          <div class="hero-eyebrow"><span>DEEPIQ × MIPHI</span><i></i><span>ENTERPRISE STORAGE</span></div>
          <h1 id="miphi-title"><span>MiPhi</span><em>Semiconductors</em></h1>
          <p class="hero-manifesto">Powering the data behind<br />the AI-driven future.</p>
          <p class="hero-lead">Enterprise storage. Engineered for performance. Built for what’s next.</p>
          <div class="hero-actions">
            <a class="primary-button" href="/#contact">Explore with DeepIQ <span aria-hidden="true">↗</span></a>
            <a class="ghost-button" href="#foundation">Discover MiPhi <span aria-hidden="true">↓</span></a>
          </div>
        </div>
        <aside class="agent-card" aria-label="Regional availability"><span class="live-dot"></span><div><small>AUTHORISED AGENT</small><strong>DeepIQ · Sri Lanka</strong></div></aside>
        <div class="hero-spec" aria-hidden="true"><span>NAND</span><i></i><span>SSD</span><i></i><span>AI</span></div>
      </section>

      <section class="foundation-section section-space" id="foundation" aria-labelledby="foundation-heading">
        <div class="section-marker reveal"><span>01</span><i></i><p>THE DATA FOUNDATION</p></div>
        <div class="foundation-grid">
          <div class="foundation-heading reveal"><p class="overline">DATA MOVES EVERYTHING</p><h2 id="foundation-heading">The future needs<br /><em>a faster foundation.</em></h2></div>
          <div class="foundation-copy reveal">
            <p class="lead">Data is the foundation of every digital business—and as AI, cloud computing and high-performance applications accelerate, the demand for faster, more reliable and higher-capacity storage has never been greater.</p>
            <p class="declaration">MiPhi Semiconductors is building the storage infrastructure for this new era.</p>
          </div>
        </div>
        <div class="data-pulse reveal" aria-hidden="true"><span>DATA</span><i></i><b></b><i></i><b></b><i></i><strong>INTELLIGENCE</strong></div>
      </section>

      <section class="venture-section" aria-labelledby="venture-heading">
        <div class="venture-visual" aria-hidden="true">
          <div class="chip-stage"><span class="chip-ring ring-one"></span><span class="chip-ring ring-two"></span><div class="chip-core"><small>STORAGE</small><strong>MΦ</strong><small>ENGINE</small></div><i class="chip-node node-one"></i><i class="chip-node node-two"></i><i class="chip-node node-three"></i></div>
          <span class="visual-label label-top">NAND TECHNOLOGY</span><span class="visual-label label-bottom">INDIAN MANUFACTURING</span>
        </div>
        <div class="venture-copy section-space">
          <div class="section-marker reveal"><span>02</span><i></i><p>THE JOINT VENTURE</p></div>
          <h2 class="reveal" id="venture-heading">Global technology.<br /><em>Built in India.</em></h2>
          <p class="lead reveal">A strategic joint venture between Micromax Informatics and Phison Electronics, MiPhi combines India's manufacturing strength with Phison's globally proven NAND storage technology to design and manufacture enterprise-grade SSD and storage solutions in India.</p>
          <div class="venture-equation reveal" aria-label="MiPhi joint venture strengths">
            <article><span>01</span><strong>Micromax</strong><p>Manufacturing strength<br />and technology ecosystem</p></article><i aria-hidden="true">+</i>
            <article><span>02</span><strong>Phison</strong><p>Globally proven NAND<br />storage technology</p></article><i aria-hidden="true">=</i>
            <article class="equation-result"><span>03</span><strong>MiPhi</strong><p>Enterprise-grade storage<br />engineered in India</p></article>
          </div>
        </div>
      </section>

      <section class="workload-section section-space" id="workloads" aria-labelledby="workload-heading">
        <div class="section-marker reveal"><span>03</span><i></i><p>BUILT FOR DEMANDING WORKLOADS</p></div>
        <div class="workload-head">
          <h2 class="reveal" id="workload-heading">Built for the world's<br /><em>most demanding workloads.</em></h2>
          <p class="reveal">From AI infrastructure and cloud platforms to enterprise applications and modern data centres, MiPhi delivers storage engineered for performance, endurance, capacity and reliability.</p>
        </div>
        <div class="workload-grid">
          <button class="workload-card reveal" type="button" data-workload-key="ai" aria-haspopup="dialog" aria-controls="workload-wizard"><span>01</span><div class="workload-motion motion-workload-ai" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">✦</div><h3>AI &amp;<br />Machine Learning</h3><p>Feed data-intensive models and inference workloads at speed.</p></button>
          <button class="workload-card reveal" type="button" data-workload-key="cloud" aria-haspopup="dialog" aria-controls="workload-wizard"><span>02</span><div class="workload-motion motion-workload-cloud" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">☁</div><h3>Cloud<br />Computing</h3><p>Storage performance designed for scalable cloud platforms.</p></button>
          <button class="workload-card reveal" type="button" data-workload-key="applications" aria-haspopup="dialog" aria-controls="workload-wizard"><span>03</span><div class="workload-motion motion-workload-apps" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">◇</div><h3>Enterprise<br />Applications</h3><p>Consistent availability for mission-critical applications.</p></button>
          <button class="workload-card reveal" type="button" data-workload-key="datacentre" aria-haspopup="dialog" aria-controls="workload-wizard"><span>04</span><div class="workload-motion motion-workload-datacentre" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">▦</div><h3>Modern<br />Data Centres</h3><p>High-density capability for the next generation of infrastructure.</p></button>
          <button class="workload-card reveal" type="button" data-workload-key="hpc" aria-haspopup="dialog" aria-controls="workload-wizard"><span>05</span><div class="workload-motion motion-workload-hpc" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">⌁</div><h3>High-Performance<br />Computing</h3><p>Throughput and endurance for advanced compute environments.</p></button>
          <button class="workload-card reveal" type="button" data-workload-key="infrastructure" aria-haspopup="dialog" aria-controls="workload-wizard"><span>06</span><div class="workload-motion motion-workload-infrastructure" aria-hidden="true"><span></span><span></span><span></span><i></i></div><div class="workload-icon" aria-hidden="true">◎</div><h3>Digital<br />Infrastructure</h3><p>Reliable storage foundations that can grow with the business.</p></button>
        </div>
        <p class="workload-summary reveal">Whether building new infrastructure or modernising existing environments, MiPhi solutions are designed to deliver the performance required today while providing the scalability needed for tomorrow.</p>
      </section>

      <dialog class="workload-wizard" id="workload-wizard" aria-labelledby="workload-wizard-title">
        <div class="workload-wizard-shell">
          <button class="workload-wizard-close" type="button" data-workload-wizard-close aria-label="Close workload explorer"><span aria-hidden="true">&times;</span></button>

          <aside class="workload-wizard-selection">
            <p class="workload-wizard-overline">Selected workload</p>
            <div class="workload-wizard-selected-card" data-workload-wizard-selected>
              <span class="workload-wizard-selected-number" data-workload-wizard-number>01</span>
              <div class="workload-wizard-selected-icon" data-workload-wizard-icon aria-hidden="true">&#10022;</div>
              <h2 id="workload-wizard-title" tabindex="-1" data-workload-wizard-title>AI &amp; Machine Learning</h2>
              <p data-workload-wizard-summary>Feed data-intensive models and inference workloads at speed.</p>
            </div>
            <div class="workload-wizard-source-status"><span><i></i>MiPhi workload</span><b>Ready</b></div>
            <p class="workload-wizard-selection-note">A guided view of how MiPhi storage discovers demand, accelerates data and protects each workload.</p>
          </aside>

          <section class="workload-wizard-main" aria-label="Storage workload onboarding">
            <header class="workload-wizard-header">
              <div>
                <p data-workload-wizard-step-label>Step 01 / 03</p>
                <h3 data-workload-wizard-step-title>Map the workload</h3>
                <span data-workload-wizard-step-description>Discover the data path, storage tiers and compute dependencies behind this workload.</span>
              </div>
              <span class="workload-wizard-live"><i></i>Live simulation</span>
            </header>

            <ol class="workload-wizard-steps" aria-label="Workload explorer steps">
              <li><button type="button" class="is-active" data-workload-wizard-step="0" aria-current="step"><span>01</span><b>Discover</b><i></i></button></li>
              <li><button type="button" data-workload-wizard-step="1"><span>02</span><b>Accelerate</b><i></i></button></li>
              <li><button type="button" data-workload-wizard-step="2"><span>03</span><b>Protect</b><i></i></button></li>
            </ol>

            <div class="workload-wizard-stage" role="img" aria-label="Animated AI and machine learning storage topology" data-workload-wizard-stage>
              <canvas id="workload-wizard-canvas" aria-hidden="true"></canvas>
              <div class="workload-wizard-stage-hud"><span>Live data path</span><b data-workload-wizard-scene-label>AI &amp; Machine Learning</b></div>
              <div class="workload-wizard-stage-legend" aria-hidden="true">
                <span><i></i><b data-workload-wizard-signal="0">GPU cluster</b></span>
                <span><i></i><b data-workload-wizard-signal="1">Model data</b></span>
                <span><i></i><b data-workload-wizard-signal="2">NVMe tier</b></span>
              </div>
            </div>

            <div class="workload-wizard-detail-grid">
              <div class="workload-wizard-insight" aria-live="polite">
                <span>What happens here</span>
                <p data-workload-wizard-insight>MiPhi maps model data from the NVMe tier through the fabric to every accelerator.</p>
                <ul data-workload-wizard-points></ul>
              </div>
              <div class="workload-wizard-metrics" aria-label="Live example metrics">
                <article><span data-workload-wizard-metric-label="0">GPUs</span><strong data-workload-wizard-metric-value="0">32</strong><i></i></article>
                <article><span data-workload-wizard-metric-label="1">Read rate</span><strong data-workload-wizard-metric-value="1">24 GB/s</strong><i></i></article>
                <article><span data-workload-wizard-metric-label="2">Queue</span><strong data-workload-wizard-metric-value="2">18</strong><i></i></article>
              </div>
            </div>

            <footer class="workload-wizard-footer">
              <button type="button" class="workload-wizard-back" data-workload-wizard-prev disabled><span aria-hidden="true">&larr;</span> Back</button>
              <span data-workload-wizard-progress>1 of 3</span>
              <button type="button" class="workload-wizard-next" data-workload-wizard-next>Continue <span aria-hidden="true">&rarr;</span></button>
            </footer>
          </section>
        </div>
      </dialog>

      <section class="engineering-section" id="engineering" aria-labelledby="engineering-heading">
        <div class="engineering-track" aria-hidden="true">
          <span>PERFORMANCE</span><i>•</i><span>ENDURANCE</span><i>•</i><span>CAPACITY</span><i>•</i><span>RELIABILITY</span><i>•</i>
          <span>PERFORMANCE</span><i>•</i><span>ENDURANCE</span><i>•</i><span>CAPACITY</span><i>•</i><span>RELIABILITY</span><i>•</i>
        </div>
        <div class="engineering-inner section-space">
          <div class="engineering-copy reveal"><p class="overline">ENTERPRISE-GRADE STORAGE</p><h2 id="engineering-heading">Engineered across<br /><em>every dimension.</em></h2></div>
          <div class="engineering-detail reveal">
            <p>MiPhi's enterprise SSD portfolio is designed around four qualities that modern infrastructure cannot compromise.</p>
            <div class="quality-list"><span><b>01</b>Performance<i></i></span><span><b>02</b>Endurance<i></i></span><span><b>03</b>Capacity<i></i></span><span><b>04</b>Reliability<i></i></span></div>
          </div>
        </div>
      </section>

      <section class="india-section section-space" aria-labelledby="india-heading">
        <div class="india-circuit" aria-hidden="true"><span class="circuit-line line-a"></span><span class="circuit-line line-b"></span><span class="circuit-line line-c"></span><i class="circuit-dot dot-a"></i><i class="circuit-dot dot-b"></i><i class="circuit-dot dot-c"></i><strong>IN</strong></div>
        <div class="section-marker reveal"><span>04</span><i></i><p>MAKE IN INDIA</p></div>
        <div class="india-grid">
          <h2 class="reveal" id="india-heading">Global expertise.<br />Indian engineering.<br /><em>Enterprise-grade storage.</em></h2>
          <div class="india-copy reveal"><p class="lead">MiPhi brings together Phison's deep expertise in NAND and storage technology with Micromax's extensive technology and manufacturing ecosystem in India.</p><p>Driven by the “Make in India” vision, MiPhi is helping build a stronger semiconductor and digital infrastructure ecosystem—developing advanced storage solutions for India and global markets.</p></div>
        </div>
      </section>

      <section class="intelligence-section" aria-labelledby="intelligence-heading">
        <canvas id="memory-canvas" aria-hidden="true"></canvas>
        <div class="memory-stack" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div>
        <div class="intelligence-inner section-space">
          <div class="section-marker reveal"><span>05</span><i></i><p>STORAGE THAT ENABLES INTELLIGENCE</p></div>
          <div class="intelligence-grid">
            <div class="reveal"><h2 id="intelligence-heading">Behind every AI workload<br /><em>is the data that powers it.</em></h2></div>
            <div class="intelligence-copy reveal"><p class="lead">AI is transforming how organisations compute, analyse and operate. Behind every AI workload is a storage infrastructure capable of feeding data at speed, handling demanding workloads and delivering consistent performance.</p><p class="declaration">MiPhi is building that foundation.</p><p>From intelligent computing to next-generation data centres, MiPhi's enterprise storage solutions are designed to help organisations turn data into performance, and performance into innovation.</p></div>
          </div>
          <div class="value-flow reveal" aria-label="How MiPhi storage enables innovation"><span><b>01</b>DATA</span><i>→</i><span><b>02</b>PERFORMANCE</span><i>→</i><span><b>03</b>INTELLIGENCE</span><i>→</i><span><b>04</b>INNOVATION</span></div>
        </div>
      </section>

      <section class="sri-lanka-section section-space" id="sri-lanka" aria-labelledby="sri-lanka-heading">
        <div class="region-visual" aria-hidden="true"><span class="region-ring ring-a"></span><span class="region-ring ring-b"></span><i></i><small>06.9271° N<br />79.8612° E</small></div>
        <div class="section-marker reveal"><span>06</span><i></i><p>MIPHI IN SRI LANKA</p></div>
        <div class="region-grid">
          <div class="reveal"><p class="overline">AUTHORISED LOCAL ACCESS</p><h2 id="sri-lanka-heading">Enterprise storage.<br /><em>Now closer.</em></h2></div>
          <div class="region-copy reveal"><p class="lead">MiPhi has appointed DeepIQ as an Authorised Agent in Sri Lanka, enabling organisations across the country to access MiPhi's enterprise storage technology and explore solutions aligned with their infrastructure, performance and future growth requirements.</p><div class="region-badge"><span class="live-dot"></span><div><small>REGIONAL PARTNER</small><strong>DeepIQ · Sri Lanka</strong></div></div></div>
        </div>
      </section>

      <section class="final-cta" aria-labelledby="final-heading">
        <div class="final-grid" aria-hidden="true"></div><div class="final-chip" aria-hidden="true"><span></span><i></i><b></b></div>
        <div class="final-inner reveal">
          <p class="overline">MIPHI SEMICONDUCTORS</p>
          <h2 id="final-heading">Powering data.<br /><em>Enabling AI.</em><br />Accelerating tomorrow.</h2>
          <p>Explore MiPhi enterprise storage solutions with DeepIQ.</p>
          <div class="final-actions"><a class="primary-button" href="/#contact">Talk to DeepIQ <span aria-hidden="true">↗</span></a><a class="official-link" href="https://www.miphi.in/" target="_blank" rel="noopener noreferrer">Visit MiPhi <span aria-hidden="true">↗</span></a></div>
        </div>
      </section>
    </main>

    <footer class="miphi-footer">
      <a class="deepiq-brand footer-brand" href="/"><img src="/deepiq-logo.svg" alt="" /><span>DEEP</span><b>IQ</b></a>
      <p>Authorised MiPhi Agent<br />Sri Lanka</p>
      <div><a href="https://www.miphi.in/" target="_blank" rel="noopener noreferrer">miphi.in ↗</a><span>© <b id="year"></b> DeepIQ</span></div>
    </footer>`};export{a as default};
